//! Image generation: user-configured endpoint/model, agent-invoked tool.
//!
//! The agent decides *when* to generate and the prompt; the model is fixed by
//! the user's `image.json`. Generated bytes are stored locally and returned as
//! asset references, never as base64 in the model context.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use async_trait::async_trait;
use base64::Engine;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use tokio_util::sync::CancellationToken;

use crate::assets::FsAssetStore;
use crate::json_store::JsonStore;
use phi_contracts::auxiliary::{
    ImageAsset, ImageConfigInput, ImagePort, ImageRequest, ImageResponse, ImageStatus, ImageUsage,
};
use phi_contracts::ports::{
    SideEffect, ToolCall, ToolContext, ToolDefinition, ToolOutput, ToolPort,
};
use phi_contracts::provider::SecretRef;
use phi_contracts::util::truncate_chars;
use phi_contracts::{SLOT_IMAGE_GENERATE, SLOT_TOOL_PROVIDER};
use phi_domain::agent::AgentRole;
use phi_domain::events::DomainEvent;
use phi_i18n as i18n;
use phi_kernel::event_bus::EventBus;
use phi_kernel::lifecycle::{Plugin, PluginContext};
use phi_kernel::ports::{ClockPort, LogPort};
use phi_kernel::registry::Contribution;

use crate::memory::redact_secrets;

const MAX_BYTES_LIMIT: u64 = 50 * 1024 * 1024;
const DEFAULT_MAX_BYTES: u64 = 20 * 1024 * 1024;
const DEFAULT_MAX_PER_TURN: u32 = 4;

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
struct ImageConfig {
    enabled: bool,
    provider: String,
    base_url: String,
    api_key: Option<SecretRef>,
    model: String,
    size: Option<String>,
    quality: Option<String>,
    format: String,
    max_per_turn: u32,
    max_bytes: u64,
    egress_granted: bool,
}

impl Default for ImageConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            provider: String::new(),
            base_url: String::new(),
            api_key: None,
            model: String::new(),
            size: None,
            quality: None,
            format: "png".to_string(),
            max_per_turn: DEFAULT_MAX_PER_TURN,
            max_bytes: DEFAULT_MAX_BYTES,
            egress_granted: false,
        }
    }
}

pub struct ImagePlugin {
    config: JsonStore<ImageConfig>,
    assets: FsAssetStore,
    client: reqwest::Client,
    bus: Arc<EventBus>,
    clock: Arc<dyn ClockPort>,
    log: Arc<dyn LogPort>,
    turn_counts: Mutex<HashMap<String, u32>>,
}

impl ImagePlugin {
    pub fn new(
        config_path: std::path::PathBuf,
        assets_root: std::path::PathBuf,
        bus: Arc<EventBus>,
        clock: Arc<dyn ClockPort>,
        log: Arc<dyn LogPort>,
    ) -> Self {
        Self {
            config: JsonStore::load(config_path),
            assets: FsAssetStore::new(assets_root),
            client: reqwest::Client::new(),
            bus,
            clock,
            log,
            turn_counts: Mutex::new(HashMap::new()),
        }
    }

    fn reason(config: &ImageConfig) -> Option<String> {
        if !config.enabled {
            return Some(i18n::t("Image generation is disabled"));
        }
        if config.provider.trim().is_empty()
            || config.base_url.trim().is_empty()
            || config.model.trim().is_empty()
        {
            return Some(i18n::t("Image generation is not configured"));
        }
        if !config.egress_granted {
            return Some(i18n::t("Image prompt egress is not granted"));
        }
        if config
            .api_key
            .as_ref()
            .is_none_or(|key| !key.is_configured())
        {
            return Some(i18n::t("Image API key is not configured"));
        }
        None
    }

    fn status_of(config: &ImageConfig) -> ImageStatus {
        let reason = Self::reason(config);
        ImageStatus {
            configured: !config.provider.trim().is_empty()
                && !config.base_url.trim().is_empty()
                && !config.model.trim().is_empty(),
            enabled: config.enabled,
            ready: reason.is_none(),
            provider: config.provider.clone(),
            base_url: config.base_url.clone(),
            model: config.model.clone(),
            size: config.size.clone(),
            quality: config.quality.clone(),
            format: config.format.clone(),
            max_per_turn: config.max_per_turn,
            egress_granted: config.egress_granted,
            reason,
        }
    }

    fn apply_input(current: &ImageConfig, input: ImageConfigInput) -> Result<ImageConfig, String> {
        let provider = input.provider.trim().to_ascii_lowercase();
        if !provider.is_empty() && provider != "openai_images" && provider != "gemini_images" {
            return Err(i18n::t_args(
                "Unknown image provider {provider}; expected openai_images or gemini_images",
                &[("provider", provider)],
            ));
        }
        let base_url = input.base_url.trim().trim_end_matches('/').to_string();
        if !base_url.is_empty()
            && !base_url.starts_with("http://")
            && !base_url.starts_with("https://")
        {
            return Err(i18n::t(
                "The image endpoint must start with http:// or https://",
            ));
        }
        let format = if input.format.trim().is_empty() {
            "png".to_string()
        } else {
            input.format.trim().to_ascii_lowercase()
        };
        if !matches!(format.as_str(), "png" | "jpeg" | "webp" | "gif" | "svg") {
            return Err(i18n::t_args(
                "Unsupported image format {format}; expected png, jpeg, webp, gif or svg",
                &[("format", format)],
            ));
        }
        let api_key = match input.api_key {
            Some(value) => SecretRef::normalize(&value),
            None => current.api_key.clone(),
        };
        Ok(ImageConfig {
            enabled: input.enabled,
            provider,
            base_url,
            api_key,
            model: input.model.trim().to_string(),
            size: input
                .size
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty()),
            quality: input
                .quality
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty()),
            format,
            max_per_turn: input
                .max_per_turn
                .clamp(1, 8)
                .max(if input.max_per_turn == 0 {
                    DEFAULT_MAX_PER_TURN
                } else {
                    1
                }),
            max_bytes: input.max_bytes.clamp(1024 * 1024, MAX_BYTES_LIMIT).max(
                if input.max_bytes == 0 {
                    DEFAULT_MAX_BYTES
                } else {
                    1
                },
            ),
            egress_granted: input.egress_granted,
        })
    }

    fn prompt_preview(prompt: &str) -> String {
        let redacted = redact_secrets(prompt).text;
        truncate_chars(&redacted, 200)
    }

    async fn call_openai(
        &self,
        config: &ImageConfig,
        request: &ImageRequest,
    ) -> Result<(Vec<(Vec<u8>, String)>, Option<ImageUsage>), String> {
        let key = config
            .api_key
            .as_ref()
            .ok_or_else(|| i18n::t("Image API key is not configured"))?
            .resolve()?;
        let url = if config.base_url.ends_with("/images/generations") {
            config.base_url.clone()
        } else {
            format!("{}/images/generations", config.base_url)
        };
        let mut body = json!({
            "model": config.model,
            "prompt": request.prompt,
            "n": request.count,
            "response_format": "b64_json",
        });
        if let Some(size) = request.size.as_ref().or(config.size.as_ref()) {
            body["size"] = json!(size);
        }
        if let Some(quality) = config.quality.as_ref() {
            body["quality"] = json!(quality);
        }
        let response = self
            .client
            .post(url)
            .bearer_auth(key)
            .json(&body)
            .timeout(Duration::from_secs(120))
            .send()
            .await
            .map_err(|error| {
                i18n::t_args(
                    "Image request failed: {error}",
                    &[("error", error.to_string())],
                )
            })?;
        let status = response.status();
        let text = response.text().await.unwrap_or_default();
        if !status.is_success() {
            return Err(i18n::t_args(
                "Image provider returned {status}: {body}",
                &[
                    ("status", status.as_u16().to_string()),
                    ("body", truncate_chars(&text, 1000)),
                ],
            ));
        }
        let value: Value = serde_json::from_str(&text).map_err(|error| {
            i18n::t_args(
                "Image provider returned invalid JSON: {error}",
                &[("error", error.to_string())],
            )
        })?;
        let mut images = Vec::new();
        for item in value["data"].as_array().into_iter().flatten() {
            let Some(encoded) = item["b64_json"].as_str() else {
                if item["url"].is_string() {
                    return Err(i18n::t(
                        "The image provider returned a remote URL; configure it to return base64 data instead",
                    ));
                }
                continue;
            };
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(encoded)
                .map_err(|error| {
                    i18n::t_args(
                        "Image data is not valid base64: {error}",
                        &[("error", error.to_string())],
                    )
                })?;
            images.push((bytes, String::new()));
        }
        if images.is_empty() {
            return Err(i18n::t("The image provider returned no images"));
        }
        Ok((
            images,
            Some(ImageUsage {
                images: request.count,
            }),
        ))
    }

    async fn call_gemini(
        &self,
        config: &ImageConfig,
        request: &ImageRequest,
    ) -> Result<(Vec<(Vec<u8>, String)>, Option<ImageUsage>), String> {
        let key = config
            .api_key
            .as_ref()
            .ok_or_else(|| i18n::t("Image API key is not configured"))?
            .resolve()?;
        let url = format!(
            "{}/models/{}:generateContent",
            config.base_url, config.model
        );
        let body = json!({
            "contents": [{ "parts": [{ "text": request.prompt }] }],
            "generationConfig": { "responseModalities": ["TEXT", "IMAGE"] }
        });
        let response = self
            .client
            .post(url)
            .header("x-goog-api-key", key)
            .json(&body)
            .timeout(Duration::from_secs(120))
            .send()
            .await
            .map_err(|error| {
                i18n::t_args(
                    "Image request failed: {error}",
                    &[("error", error.to_string())],
                )
            })?;
        let status = response.status();
        let text = response.text().await.unwrap_or_default();
        if !status.is_success() {
            return Err(i18n::t_args(
                "Image provider returned {status}: {body}",
                &[
                    ("status", status.as_u16().to_string()),
                    ("body", truncate_chars(&text, 1000)),
                ],
            ));
        }
        let value: Value = serde_json::from_str(&text).map_err(|error| {
            i18n::t_args(
                "Image provider returned invalid JSON: {error}",
                &[("error", error.to_string())],
            )
        })?;
        let mut images = Vec::new();
        for candidate in value["candidates"].as_array().into_iter().flatten() {
            for part in candidate["content"]["parts"]
                .as_array()
                .into_iter()
                .flatten()
            {
                let Some(encoded) = part["inlineData"]["data"].as_str() else {
                    continue;
                };
                let mime = part["inlineData"]["mimeType"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string();
                let bytes = base64::engine::general_purpose::STANDARD
                    .decode(encoded)
                    .map_err(|error| {
                        i18n::t_args(
                            "Image data is not valid base64: {error}",
                            &[("error", error.to_string())],
                        )
                    })?;
                images.push((bytes, mime));
            }
        }
        if images.is_empty() {
            return Err(i18n::t("The image provider returned no images"));
        }
        Ok((images, None))
    }

    fn sniff_mime(bytes: &[u8]) -> Option<&'static str> {
        if bytes.starts_with(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]) {
            return Some("image/png");
        }
        if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
            return Some("image/jpeg");
        }
        if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
            return Some("image/webp");
        }
        if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
            return Some("image/gif");
        }
        let head = String::from_utf8_lossy(&bytes[..bytes.len().min(512)]);
        if head.trim_start().starts_with("<svg") || head.contains("<svg") {
            return Some("image/svg+xml");
        }
        None
    }
}

#[async_trait]
impl ImagePort for ImagePlugin {
    fn status(&self) -> ImageStatus {
        Self::status_of(&self.config.snapshot())
    }

    fn configure(&self, input: ImageConfigInput) -> Result<ImageStatus, String> {
        self.config.update(|current| {
            let next = Self::apply_input(current, input)?;
            *current = next;
            Ok::<(), String>(())
        })??;
        Ok(self.status())
    }

    async fn generate(
        &self,
        request: ImageRequest,
        session_id: Option<String>,
        cancel: CancellationToken,
    ) -> Result<ImageResponse, String> {
        let config = self.config.snapshot();
        if let Some(reason) = Self::reason(&config) {
            return Err(reason);
        }
        let prompt = request.prompt.trim().to_string();
        if prompt.is_empty() {
            return Err(i18n::t("Image prompt is empty"));
        }
        if prompt.chars().count() > 4000 {
            return Err(i18n::t("Image prompt is too long (max 4000 characters)"));
        }
        let count = request.count.clamp(1, 4);
        let request = ImageRequest {
            prompt: prompt.clone(),
            count,
            ..request
        };
        let result = tokio::select! {
            result = async {
                match config.provider.as_str() {
                    "openai_images" => self.call_openai(&config, &request).await,
                    "gemini_images" => self.call_gemini(&config, &request).await,
                    other => Err(i18n::t_args(
                        "Unsupported image provider: {provider}",
                        &[("provider", other.to_string())],
                    )),
                }
            } => result,
            _ = cancel.cancelled() => return Err("cancelled".to_string()),
        };
        let (images, usage) = result?;
        let now = self.clock.now_rfc3339();
        let mut assets = Vec::new();
        for (bytes, provider_mime) in images {
            if bytes.len() as u64 > config.max_bytes {
                return Err(i18n::t_args(
                    "Image is too large ({bytes} bytes; max {max})",
                    &[
                        ("bytes", bytes.len().to_string()),
                        ("max", config.max_bytes.to_string()),
                    ],
                ));
            }
            let sniffed = Self::sniff_mime(&bytes)
                .ok_or_else(|| i18n::t("The image provider returned an unsupported file format"))?;
            let mime = if provider_mime.trim().is_empty() {
                sniffed.to_string()
            } else if provider_mime == sniffed {
                provider_mime
            } else {
                return Err(i18n::t_args(
                    "Image MIME mismatch: provider said {provider}, bytes look like {sniffed}",
                    &[
                        ("provider", provider_mime),
                        ("sniffed", sniffed.to_string()),
                    ],
                ));
            };
            let asset = self.assets.put(
                &bytes,
                ImageAsset {
                    asset_id: String::new(),
                    mime,
                    width: None,
                    height: None,
                    model: config.model.clone(),
                    prompt_preview: Self::prompt_preview(&prompt),
                    session_id: session_id.clone(),
                    created_at: now.clone(),
                },
            )?;
            let _ = self.bus.publish(
                session_id.as_deref().unwrap_or("node"),
                "plugin-image",
                &DomainEvent::ImageGenerated {
                    asset_id: asset.asset_id.clone(),
                    session_id: session_id.clone(),
                    model: asset.model.clone(),
                    mime: asset.mime.clone(),
                    width: asset.width,
                    height: asset.height,
                    prompt_preview: asset.prompt_preview.clone(),
                },
            );
            assets.push(asset);
        }
        self.log
            .info(&format!("generated {} image asset(s)", assets.len()));
        Ok(ImageResponse { assets, usage })
    }

    fn list(&self, session_id: Option<&str>) -> Vec<ImageAsset> {
        self.assets.list(session_id)
    }

    fn delete(&self, asset_id: &str) -> Result<bool, String> {
        let meta = self.assets.meta(asset_id).ok();
        let deleted = self.assets.delete(asset_id)?;
        if deleted {
            let _ = self.bus.publish(
                meta.as_ref()
                    .and_then(|asset| asset.session_id.as_deref())
                    .unwrap_or("node"),
                "plugin-image",
                &DomainEvent::ImageDeleted {
                    asset_id: asset_id.to_string(),
                },
            );
        }
        Ok(deleted)
    }

    fn bytes(&self, asset_id: &str) -> Result<Vec<u8>, String> {
        self.assets.read(asset_id)
    }
}

#[async_trait]
impl ToolPort for ImagePlugin {
    fn definitions(&self) -> Vec<ToolDefinition> {
        vec![ToolDefinition {
            id: "image_generate".to_string(),
            name: "image_generate".to_string(),
            description: "Generate one or more images with the user-configured image model. The model is fixed by the user; you choose only the prompt and, optionally, a supported size. Returns local asset ids that the host can render.".to_string(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "prompt": { "type": "string", "description": "What to draw" },
                    "size": { "type": "string", "description": "Optional provider-supported size" },
                    "count": { "type": "integer", "minimum": 1, "maximum": 4 },
                    "reference_assets": { "type": "array", "items": { "type": "string" } }
                },
                "required": ["prompt"]
            }),
            side_effect: SideEffect::None,
        }]
    }

    async fn invoke(
        &self,
        call: &ToolCall,
        ctx: &ToolContext,
        cancel: CancellationToken,
    ) -> Result<ToolOutput, String> {
        if ctx.role != AgentRole::Lead {
            return Ok(ToolOutput {
                content: i18n::t("Only the lead agent can generate images"),
                is_error: true,
            });
        }
        let prompt = call
            .input
            .get("prompt")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        let Some(prompt) = prompt else {
            return Ok(ToolOutput {
                content: i18n::t("Missing required argument: prompt"),
                is_error: true,
            });
        };
        let status = self.status();
        if !status.ready {
            return Ok(ToolOutput {
                content: status
                    .reason
                    .unwrap_or_else(|| i18n::t("Image generation is not ready")),
                is_error: true,
            });
        }
        let config = self.config.snapshot();
        let requested = call
            .input
            .get("count")
            .and_then(Value::as_u64)
            .unwrap_or(1)
            .clamp(1, 4) as u32;
        let turn_key = format!("{}:{}", ctx.session_id, ctx.turn_id);
        {
            let counts = self.turn_counts.lock().unwrap();
            let used = counts.get(&turn_key).copied().unwrap_or(0);
            if used + requested > config.max_per_turn {
                return Ok(ToolOutput {
                    content: i18n::t_args(
                        "Image generation limit reached for this turn ({used}+{requested} > {max})",
                        &[
                            ("used", used.to_string()),
                            ("requested", requested.to_string()),
                            ("max", config.max_per_turn.to_string()),
                        ],
                    ),
                    is_error: true,
                });
            }
        }
        let request = ImageRequest {
            prompt: prompt.to_string(),
            size: call
                .input
                .get("size")
                .and_then(Value::as_str)
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty()),
            count: requested,
            reference_assets: call
                .input
                .get("reference_assets")
                .and_then(Value::as_array)
                .map(|values| {
                    values
                        .iter()
                        .filter_map(Value::as_str)
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default(),
        };
        if !request.reference_assets.is_empty() {
            return Ok(ToolOutput {
                content: i18n::t("Reference images are not supported by this image adapter yet"),
                is_error: true,
            });
        }
        let response = match self
            .generate(request, Some(ctx.session_id.clone()), cancel)
            .await
        {
            Ok(response) => response,
            Err(error) => {
                return Ok(ToolOutput {
                    content: error,
                    is_error: true,
                });
            }
        };
        self.turn_counts
            .lock()
            .unwrap()
            .entry(turn_key)
            .and_modify(|count| *count += response.assets.len() as u32)
            .or_insert(response.assets.len() as u32);
        Ok(ToolOutput {
            content: serde_json::to_string(&json!({
                "model": self.config.snapshot().model,
                "assets": response.assets,
            }))
            .unwrap_or_else(|_| i18n::t("Image generated")),
            is_error: false,
        })
    }
}

impl Plugin for ImagePlugin {
    fn id(&self) -> &'static str {
        "plugin-image"
    }

    fn activate(&self, _ctx: &PluginContext) -> Result<Vec<Contribution>, String> {
        Ok(vec![
            Contribution {
                plugin_id: self.id().to_string(),
                slot: SLOT_IMAGE_GENERATE.to_string(),
                id: "default".to_string(),
            },
            Contribution {
                plugin_id: self.id().to_string(),
                slot: SLOT_TOOL_PROVIDER.to_string(),
                id: "image".to_string(),
            },
        ])
    }
}
